response.text:
 {
  "title": "HCV adherence in Zimbabwe",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "title": "Who quits treatment?",
      "goal": "See how poor adherence fills the quit-treatment compartment.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence",
        "lowEnd": "no one",
        "highEnd": "everyone"
      },
      "watch": "people who quit treatment (cQ)",
      "whatIf": {
        "prompt": "What if only 20% of patients adhered?",
        "parameter": "theta",
        "value": 0.2
      },
      "difference": {
        "compartment": "cQ",
        "summary": "at",
        "at": 60,
        "time": 60,
        "relation": "higher",
        "by": 0.003
      },
      "effect": "With only 20% adherence, the quit-treatment group at year 60 is higher by more than 0.003.",
      "prediction": {
        "prompt": "At year 60, will the low-adherence world have more or fewer people who quit treatment?",
        "claimed": "more quitters",
        "other": "fewer quitters"
      },
      "passage": {
        "title": "Treatment adherence parameter",
        "quote": "We define $θ$ as the proportion of individuals under treatment who successfully adhere to it."
      },
      "carryForward": "Next, see what happens when those quitters become more infectious."
    },
    {
      "kind": "idea",
      "title": "Quitters spread more",
      "goal": "See how much more virus quitters pass on.",
      "control": {
        "parameter": "beta3",
        "label": "Transmission from quitters",
        "lowEnd": "low",
        "highEnd": "high"
      },
      "watch": "acutely infected people (i)",
      "whatIf": {
        "prompt": "What if quitters transmitted twice as easily?",
        "parameter": "beta3",
        "value": 0.1
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 40,
        "time": 40,
        "relation": "higher",
        "by": 0.001
      },
      "effect": "If quitters transmit twice as easily, acutely infected people at year 40 are higher by more than 0.001.",
      "prediction": {
        "prompt": "At year 40, will the world with more infectious quitters have more or fewer acutely infected people?",
        "claimed": "more infected",
        "other": "fewer infected"
      },
      "passage": {
        "title": "Quitters are more infectious",
        "quote": "We assumed that $β_{2} < β_{3}$, since quitting treatment before reaching sustained viral response (SVR) increases HCV viral load, leading to higher transmissibility [[citation]–[citation]]."
      },
      "carryForward": "Now change the rate at which people quit treatment itself."
    },
    {
      "kind": "method",
      "title": "No quitting at all",
      "goal": "See what happens to the quit-treatment pool if no one quits.",
      "control": {
        "parameter": "delta",
        "label": "Treatment quitting rate",
        "lowEnd": "no quitting",
        "highEnd": "fast quitting"
      },
      "watch": "people who quit treatment (cQ)",
      "whatIf": {
        "prompt": "What if the quitting rate were zero?",
        "parameter": "delta",
        "value": 0
      },
      "difference": {
        "compartment": "cQ",
        "summary": "at",
        "at": 80,
        "time": 80,
        "relation": "lower",
        "by": 0.002
      },
      "effect": "With no quitting, the quit-treatment group at year 80 is lower by more than 0.002.",
      "prediction": {
        "prompt": "At year 80, will the no-quitting world have more or fewer people who quit treatment?",
        "claimed": "fewer quitters",
        "other": "more quitters"
      },
      "passage": {
        "title": "Adherence challenges",
        "quote": "Our study employed a mathematical model to explain the impact of poor treatment adherence on HCV transmission dynamics in Zimbabwe."
      },
      "carryForward": "Finally, test whether high adherence can control total infections."
    },
    {
      "kind": "result",
      "title": "Adherence above the threshold",
      "goal": "See whether high adherence lowers total acute infections over 80 years.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence",
        "lowEnd": "no one",
        "highEnd": "everyone"
      },
      "watch": "total acutely infected over 80 years (i)",
      "whatIf": {
        "prompt": "What if 80% of patients adhered?",
        "parameter": "theta",
        "value": 0.8
      },
      "difference": {
        "compartment": "i",
        "summary": "total",
        "at": null,
        "time": 80,
        "relation": "lower",
        "by": 0.05
      },
      "effect": "At 80% adherence, the total acutely infected over 80 years is lower by more than 0.05.",
      "prediction": {
        "prompt": "Over 80 years, will the high-adherence world have a larger or smaller total of acutely infected people?",
        "claimed": "smaller total",
        "other": "larger total"
      },
      "passage": {
        "title": "The 52% threshold",
        "quote": "The study demonstrated that an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Last, check how much re-susceptibility matters."
    },
    {
      "kind": "evaluation",
      "title": "Re-susceptibility barely matters",
      "goal": "See how little re-susceptibility changes recovered people.",
      "control": {
        "parameter": "phi",
        "label": "Re-susceptibility rate",
        "lowEnd": "none",
        "highEnd": "fast"
      },
      "watch": "recovered people (r)",
      "whatIf": {
        "prompt": "What if re-susceptibility were doubled?",
        "parameter": "phi",
        "value": 0.002
      },
      "difference": {
        "compartment": "r",
        "summary": "at",
        "at": 80,
        "time": 80,
        "relation": "lower",
        "by": 0.0005
      },
      "effect": "Doubling re-susceptibility makes recovered people at year 80 lower by more than 0.0005.",
      "prediction": {
        "prompt": "At year 80, will doubled re-susceptibility raise or lower recovered people?",
        "claimed": "lower recovered",
        "other": "raise recovered"
      },
      "passage": {
        "title": "Re-susceptibility is minor",
        "quote": "Our HCV model indicates that variations in re-susceptibility minimally impact outcomes, suggesting that re-susceptibility can often be excluded in such analyses."
      },
      "carryForward": "You have explored adherence, infectiousness, quitting, and re-susceptibility in HCV spread."
    }
  ],
  "limits": [
    "Each level changes exactly one parameter or starting value in the what-if world.",
    "The baseline and what-if worlds run side by side for the level's time.",
    "Predict the direction of the difference before running the what-if.",
    "Claims are checked on the paper's values and on nearby perturbations."
  ]
}
